[package]
name = "strictix-cli"
description = "strictix command-line interface"
version.workspace = true
edition.workspace = true
license.workspace = true

[[bin]]
name = "strictix"
path = "src/main.rs"

[dependencies]
strictix-core = { path = "../core" }
strictix-lints = { path = "../lints" }
serde = { version = "1", features = ["derive"] }
serde_json = "1"
toml = "0.8"
===MAIN===
//! strictix command-line interface.
//!
//! Hand-written argument parsing (no clap). Commands: check, fix,
//! explain, list. Only `--help`/`--version` exist in M0.

use std::process::ExitCode;

const USAGE: &str = "\
strictix — strict lints and suggestions for the Nix language

USAGE:
    strictix <COMMAND> [ARGS]

COMMANDS:
    check     Lint files or directories
    fix       Lint and apply automatic fixes
    explain   Explain a lint rule by code
    list      List all lint rules

OPTIONS:
    -h, --help       Print this help
    -V, --version    Print version
";

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    match args.first().map(String::as_str) {
        None | Some("-h" | "--help") => {
            print!("{USAGE}");
            ExitCode::SUCCESS
        }
        Some("-V" | "--version") => {
            println!("strictix {}", strictix_core::version());
            ExitCode::SUCCESS
        }
        Some(other) => {
            eprintln!("error: unknown command or option '{other}'\n\n{USAGE}");
            ExitCode::FAILURE
        }
    }
}

//! Diagnostics, fix machinery, rule traits, and the semantic model.
//!
//! Depends only on `strictix-syntax`. Builtin rules live in
//! `strictix-lints` and consume only this crate's public API.

#![forbid(unsafe_code)]

pub mod config;
pub mod diagnostic;
pub mod fix;
pub mod json;
pub mod rules;
pub mod semantic;

/// Reports crate version so the CLI smoke test can call into this crate.
#[must_use]
pub fn version() -> &'static str {
    env!("CARGO_PKG_VERSION")
}

//! Per-run lint configuration.
//!
//! A plain data struct: no serde here (serde is the CLI's job — the CLI
//! deserializes its own TOML DTO and converts it into this type). The
//! schema field backs the M8 `unknown-option` rule; `None` means that
//! rule is off for this run.

use std::path::PathBuf;

/// Configuration for one lint run: which rule codes are skipped and
/// whether the options schema rule is active.
#[derive(Debug, Clone, Default)]
pub struct LintConfig {
    /// Rule codes to skip. A rule whose code appears here never fires.
    pub disabled: Vec<String>,
    /// options.json path (M8); `None` = schema rule off.
    pub schema: Option<PathBuf>,
}

impl LintConfig {
    /// Whether the rule with `code` should run: true unless `disabled`
    /// contains `code`.
    #[must_use]
    pub fn is_enabled(&self, code: &str) -> bool {
        !self.disabled.iter().any(|d| d == code)
    }

    /// Builder: replace the disabled list with `codes`.
    pub fn with_disabled(mut self, codes: impl IntoIterator<Item = String>) -> Self {
        self.disabled = codes.into_iter().collect();
        self
    }

    /// Builder: set the schema path, enabling the schema rule.
    pub fn with_schema(mut self, path: impl Into<PathBuf>) -> Self {
        self.schema = Some(path.into());
        self
    }
}

//! Diagnostics: one rule finding, optionally with help and an auto fix.
//!
//! A diagnostic is the unit of linter output: a rule produces them, the
//! CLI renders them. The fix rides along here instead of being returned
//! separately so a rule emits everything the user needs to act in one
//! object — rendering and fixing then share a single path over the same
//! data, and there is no second channel for rules to forget.

use crate::fix::Fix;
use strictix_syntax::TextRange;

/// How severe a finding is.
///
/// `Warning` flags smell; `Error` flags things that are wrong enough to
/// block acceptance. The distinction is purely informational for the
/// renderer — both kinds carry fixes the same way.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Severity {
    Warning,
    Error,
}

/// A single finding from a rule, anchored to a byte range in the source.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Diagnostic {
    /// Rule code, kebab-case, e.g. "unused-let-binding".
    pub code: &'static str,
    pub severity: Severity,
    pub message: String,
    pub range: TextRange,
    /// Optional human hint, rendered below the message by the CLI.
    pub help: Option<String>,
    /// Optional automatic fix; `None` when the rule has no safe rewrite.
    pub fix: Option<Fix>,
}

impl Diagnostic {
    /// Start a diagnostic with the fields every rule must provide.
    #[must_use]
    pub fn new(
        code: &'static str,
        severity: Severity,
        message: impl Into<String>,
        range: TextRange,
    ) -> Self {
        Self {
            code,
            severity,
            message: message.into(),
            range,
            help: None,
            fix: None,
        }
    }

    /// Attach a help hint. Consumes and returns `self` so rules can
    /// build the diagnostic in one expression.
    #[must_use]
    pub fn with_help(mut self, help: impl Into<String>) -> Self {
        self.help = Some(help.into());
        self
    }

    /// Attach an automatic fix.
    #[must_use]
    pub fn with_fix(mut self, fix: Fix) -> Self {
        self.fix = Some(fix);
        self
    }

    /// The severity as the lowercase string the rendering contract uses
    /// ("warning" / "error"), shared by the one-line, human, and
    /// JSON renderers so they cannot drift apart.
    #[must_use]
    pub const fn severity_str(&self) -> &'static str {
        match self.severity {
            Severity::Warning => "warning",
            Severity::Error => "error",
        }
    }
}

//! Text-splice fixes: edit a source string without reparsing.
//!
//! Fixes are computed from the lossless tree's byte ranges, then applied
//! to the raw source text. Because the tree keeps trivia (whitespace,
//! comments) as ordinary tokens, a fix targeting a node's range replaces
//! exactly that node — formatting around it survives untouched. That is
//! the "lossless-safe" guarantee: a fix never destroys formatting.
//!
//! `apply_fixes` is the single write path. It validates every edit
//! (bounds, overlap) before splicing anything, so a buggy rule can never
//! corrupt a file silently — it gets an error it can report instead.

use strictix_syntax::TextRange;

/// One replacement: the byte range to cut out and the text to put there.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct TextEdit {
    pub range: TextRange,
    pub replacement: String,
}

impl TextEdit {
    /// Create an edit replacing `range` with `replacement`.
    ///
    /// An empty replacement deletes the range; an empty range inserts
    /// text at a point. Both are ordinary cases, not special ones.
    #[must_use]
    pub fn new(range: TextRange, replacement: impl Into<String>) -> Self {
        Self {
            range,
            replacement: replacement.into(),
        }
    }
}

/// A labeled set of edits, the payload of `Diagnostic::fix`.
///
/// The label is what a user sees in the CLI when a fix is offered, so it
/// should say what the change does ("remove unused binding"), not how.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Fix {
    pub label: String,
    pub edits: Vec<TextEdit>,
}

impl Fix {
    /// Start a fix with a human label and no edits yet.
    #[must_use]
    pub fn new(label: impl Into<String>) -> Self {
        Self {
            label: label.into(),
            edits: Vec::new(),
        }
    }

    /// Append one edit. Builder-style so multi-edit fixes read in one
    /// expression; edits may be added in any order — `apply_fixes`
    /// sorts them itself.
    #[must_use]
    pub fn edit(mut self, range: TextRange, replacement: impl Into<String>) -> Self {
        self.edits.push(TextEdit::new(range, replacement));
        self
    }
}

/// Why a set of edits could not be applied.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum FixError {
    /// Two edits' ranges intersect; applying both would corrupt the text.
    /// Touching (adjacent) ranges are fine — no overlap by definition.
    Overlap(TextRange, TextRange),
    /// An edit's range extends past the end of the source.
    InvalidRange(TextRange),
}

/// Apply `edits` to `source`, producing the edited text.
///
/// Edits may arrive in any order; they are sorted by start descending
/// (so later edits are validated first, and an overlap surfaces as soon
/// as an earlier edit's end crosses the later edit's start). Validation
/// happens before any splicing, so on error the source is untouched.
///
/// # Errors
///
/// - `InvalidRange` if an edit ends beyond `source`'s length.
/// - `Overlap` if two edits' ranges intersect.
pub fn apply_fixes(source: &str, edits: &[TextEdit]) -> Result<String, FixError> {
    let mut sorted: Vec<&TextEdit> = edits.iter().collect();
    // Descending by start: the edit closest to the end of the file
    // first. That ordering makes the overlap rule a single comparison
    // between neighbours (see below).
    sorted.sort_by(|a, b| b.range.start().cmp(&a.range.start()));

    let src_len = source.len() as u32;
    for edit in &sorted {
        if edit.range.end() > src_len {
            return Err(FixError::InvalidRange(edit.range));
        }
    }

    // Non-overlap in descending order means each later edit's start sits
    // at or after the previous (earlier) edit's end. Equal starts that
    // are non-empty fail here, which is right: they intersect.
    for pair in sorted.windows(2) {
        let later = pair[0];
        let earlier = pair[1];
        if later.range.start() < earlier.range.end() {
            return Err(FixError::Overlap(later.range, earlier.range));
        }
    }

    // Splicing walks the source once, left to right (reverse of the
    // validation order), pushing the untouched gap, the replacement, and
    // advancing past each edit's end. Validation guarantees every slice
    // index stays in bounds and no edit is skipped.
    let mut out = String::with_capacity(source.len());
    let mut pos: u32 = 0;
    for edit in sorted.iter().rev() {
        out.push_str(&source[pos as usize..edit.range.start() as usize]);
        out.push_str(&edit.replacement);
        pos = edit.range.end();
    }
    out.push_str(&source[pos as usize..]);
    Ok(out)
}

//! Rule trait, the dispatch loop, and the one registry mechanism.
//!
//! A rule is either a *node rule* (fires once per node of one
//! [SyntaxKind]) or a *file rule* (fires once per file with the lazy
//! [SemanticModel]). The registry is declared with the `rules!` macro
//! — one declaration mechanism, no hand-wired special cases.

use crate::config::LintConfig;
use crate::diagnostic::{Diagnostic, Severity};
use crate::semantic::SemanticModel;
use strictix_syntax::{SyntaxKind, SyntaxNode};

/// A single lint rule.
///
/// Node rules override [Self::node_kind] and [Self::check_node]; file
/// rules override [Self::check_file]. The default bodies do nothing, so
/// a rule implements only what it needs.
pub trait Rule: Send + Sync {
    /// Kebab-case unique id, e.g. `"unused-let-binding"`.
    fn code(&self) -> &'static str;

    /// Short human title.
    fn name(&self) -> &'static str;

    /// What the rule catches and why (1-3 sentences).
    fn description(&self) -> &'static str;

    /// Severity of the diagnostics this rule emits.
    fn severity(&self) -> Severity;

    /// `Some(kind)` makes this a node rule: [Self::check_node] fires
    /// once per node of that kind. `None` makes it a file rule:
    /// [Self::check_file] fires once per file.
    fn node_kind(&self) -> Option<SyntaxKind> {
        None
    }

    /// Inspect one node of [Self::node_kind]. Node rules must not touch
    /// the semantic model (it is lazy and only file rules build it).
    fn check_node(&self, _node: &SyntaxNode, _source: &str, _diags: &mut Vec<Diagnostic>) {}

    /// Inspect the whole file through the (lazy) semantic model.
    fn check_file(
        &self,
        _model: &SemanticModel,
        _config: &LintConfig,
        _diags: &mut Vec<Diagnostic>,
    ) {
    }
}

/// Run every enabled rule over one file.
///
/// Node rules fire once per node of their kind, in source order (the
/// `descendants()` pre-order walk). File rules fire exactly once each,
/// receiving the semantic model — which node rules never touch, so the
/// model is only built when at least one file rule is enabled.
pub fn run_rules(
    rules: &[Box<dyn Rule>],
    tree: &SyntaxNode,
    model: &SemanticModel,
    config: &LintConfig,
    source: &str,
    diags: &mut Vec<Diagnostic>,
) {
    for rule in rules {
        if !config.is_enabled(rule.code()) {
            continue;
        }
        match rule.node_kind() {
            Some(kind) => {
                for node in tree.descendants() {
                    if node.kind() == kind {
                        rule.check_node(node, source, diags);
                    }
                }
            }
            None => rule.check_file(model, config, diags),
        }
    }
}

/// Declare the whole rule registry in one place.
///
/// Takes a comma-separated list of unit-struct rule type names (plain
/// identifiers of structs implementing [Rule], declared in scope) and
/// expands to a `Vec<Box<dyn Rule>>`, one boxed instance per type:
///
/// ```text
/// rules! { UnusedLetBinding, ConstantIf }
/// ```
///
/// expands to
///
/// ```text
/// vec![Box::new(UnusedLetBinding {}), Box::new(ConstantIf {})]
/// ```
///
/// A trailing comma is accepted. Because the macro is `#[macro_export]`ed
/// it lives at the crate root: `strictix_core::rules!`.
#[macro_export]
macro_rules! rules {
    ($($rule:ident),* $(,)?) => {
        vec![$(Box::new($rule {}) as Box<dyn $crate::rules::Rule>),*]
    };
}

//! Builtin lint rules — the first customer of 's public API.
//!
//! Every rule here is declared via  — the one
//! registry mechanism — and implements the  trait. Node rules
//! (syntax-level) live in [node_rules], file rules (semantic) in
//! [file_rules], and the options-schema rule in [schema].

pub mod file_rules;
pub mod node_rules;
pub mod schema;

use file_rules::{RedundantWith, SelfReferentialLet, ShadowedBinding, UnusedFormal, UnusedLambdaParam, UnusedLetBinding};
use node_rules::{AssertTrue, ConstantIf, Tautology};
use schema::UnknownOption;
use strictix_core::rules::Rule;

/// The full builtin registry, in declaration order.
///
/// Called once per run by the CLI; the boxed rules are shared across all
/// worker threads (rules are ; the schema rule caches its
/// parsed options.json in a ).
#[must_use]
pub fn all_rules() -> Vec<Box<dyn Rule>> {
    strictix_core::rules! {
        ConstantIf,
        AssertTrue,
        Tautology,
        UnusedLetBinding,
        UnusedLambdaParam,
        UnusedFormal,
        ShadowedBinding,
        RedundantWith,
        SelfReferentialLet,
        UnknownOption,
    }
}

//! The semantic model: scopes, bindings, and references for one file.
//!
//! The syntax crate gives us a shape-aware tree but no meaning: the `a`
//! in `let a = 1; in a` and the `a` in `{ a = 1; }` are the same kind
//! of token to the parser, yet one is a definition and the other a use.
//! This module is the layer that answers "what does this ident refer
//! to?" — it records every scope, every binding, and every ident used
//! in expression position, then resolves each use to the binding its
//! name and position select under Nix scoping rules.
//!
//! The model is LAZY: [`SemanticModel::new`] only stores the source and
//! the tree. The first accessor call runs the one-time build and every
//! later accessor reuses it. Rules therefore pay for the walk only when
//! a file rule actually needs the model, and pay it exactly once per
//! file. The build lives in a `OnceLock` rather than a
//! `RefCell<Option<Built>>` because the accessors hand out `&[Binding]`
//! slices: a slice borrowed through a `RefCell` guard cannot outlive
//! the temporary guard, so the guard would have to be leaked on every
//! access. `OnceLock` gives the same build-once semantics with plain
//! borrows.
//!
//! Nix scoping, as implemented here:
//!
//! - `let` is sequential: binding *i* is visible in bindings *i+1..n*
//!   and in the body, never in its own value — the classic
//!   `let x = x;` infinite-recursion gotcha. The same rule governs
//!   formals defaults: parameter *i* is visible in the defaults of
//!   *j > i* and in the body.
//! - `rec { ... }` is the opposite: every attribute name is visible in
//!   every value, forwards and backwards.
//! - A bare (non-rec) attrset binds nothing for resolution: its names
//!   are not in scope anywhere, not even inside the attrset itself.
//!   `inherit (x) a b;` inside one still records `a` and `b` as
//!   [`BindingKind::InheritName`] entries, because rules may want to
//!   see them.
//! - `with e; body` introduces a fallback, never a shadow: the body's
//!   idents resolve lexically first, and only when the whole lexical
//!   path fails does the innermost `with` whose body covers the ident
//!   become a candidate ([`Reference::via_with`]).
//!
//! Scopes are stored as byte ranges so that "which scope governs this
//! offset" is a containment question, not a traversal one. Because the
//! walker creates scopes depth-first in source order and every new
//! scope's range nests inside its parent's, the innermost scope
//! containing an offset is simply the last-created scope whose range
//! contains it.
//!
//! The build runs in two passes. Pass 1 walks the tree once, creating
//! scopes, bindings, with sites, import sites, and collecting every
//! expression-position ident token. Pass 2 resolves each collected
//! ident against the finished scope table and fills
//! [`Binding::references`]. Two passes are required because `rec`
//! makes names visible *before* their defining value: a binding must
//! exist before any value can be resolved against it, so resolution
//! cannot happen during the walk.

use std::sync::OnceLock;

use strictix_syntax::{
    AstNode, AttrItem, AttrName, Expr, LambdaParam, Root, StringPart, SyntaxNode, SyntaxToken,
    TextRange,
};

/// The stable identity of one scope.
///
/// A u32 index into the model's internal scope table. Opaque to
/// consumers: comparing two ids tells you whether they are the same
/// scope, and nothing more.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct ScopeId(pub u32);

/// What kind of construct created a binding. Rules use this to decide
/// whether a binding is the kind they care about — an unused let
/// binding is only a finding for [`BindingKind::LetBinding`], not for a
/// formal parameter.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BindingKind {
    /// `x: ...` or a formal parameter in `{ a, b ? 1, ... }`.
    LambdaParam,
    /// The `args` in `args@{ ... }: ...` or `{ ... } @ args: ...`.
    AtName,
    /// `let a = ...;` — sequential visibility.
    LetBinding,
    /// An attribute of `rec { ... }` — mutually visible.
    RecAttr,
    /// `inherit (x) a b;` — bound in the containing block per its rules.
    InheritName,
}

/// One definition: the ident token that introduces a name, the scope it
/// lives in, and the byte ranges of the uses that resolve to it.
///
/// `references` is filled by the second pass of the build; before any
/// accessor runs it is empty.
pub struct Binding<'a> {
    /// The defining ident token (the first element of an attrpath).
    pub name: &'a SyntaxToken,
    /// The scope this binding belongs to.
    pub scope: ScopeId,
    /// Byte ranges of resolved uses, in source order (second pass).
    pub references: Vec<TextRange>,
    /// What kind of construct created this binding.
    pub kind: BindingKind,
}

/// One use of a name in expression position.
///
/// Every ident token that appears where a value is expected is a
/// reference. Ident tokens in binding position (attrpath elements,
/// inherit names, formals) and select fields (`a.b`'s `b`) are not
/// references.
pub struct Reference<'a> {
    /// The ident token used in expression position.
    pub name: &'a SyntaxToken,
    /// Index into [`SemanticModel::bindings`] when a lexical binding
    /// was found; `None` when the name is unbound lexically.
    pub resolved: Option<usize>,
    /// Index into [`SemanticModel::with_sites`] when no lexical binding
    /// was found but an enclosing `with` body covers this position.
    /// The reference still resolves to nothing (`resolved` stays
    /// `None`): statically we cannot know whether the with's attrset
    /// actually provides the name, so `via_with` only records the
    /// innermost candidate.
    pub via_with: Option<usize>,
}

/// One `with e; body` construct.
pub struct WithSite {
    /// The whole `with` expression (from `with` through the body).
    pub scope_range: TextRange,
    /// The body after the semicolon — the region the fallback covers.
    pub body_range: TextRange,
}

/// One call to `import`, plain or via `builtins.import`.
pub struct ImportSite {
    /// The whole application expression.
    pub call_range: TextRange,
    /// The argument expression (the path or string being imported).
    pub path_range: TextRange,
}

/// The internal classification of a scope. Only [`ScopeKind::Attrset`]
/// scopes are excluded from resolution: they host `inherit` names but
/// bind nothing for name lookup.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ScopeKind {
    Root,
    Let,
    Lambda,
    Rec,
    With,
    Attrset,
}

/// One scope: the byte range it governs, its parent, and the slice of
/// the model's binding table it owns.
struct Scope {
    kind: ScopeKind,
    parent: Option<ScopeId>,
    range: TextRange,
    /// Indices into [`Built::bindings`], in declaration order.
    bindings: Vec<usize>,
    /// One offset per binding in this scope: the point from which the
    /// binding becomes visible. `let` bindings and formals use this to
    /// implement sequential visibility; rec scopes ignore it
    /// (everything is visible everywhere).
    visible_from: Vec<u32>,
}

/// The result of the one-time build: everything the model knows about
/// one file. Built lazily on the first accessor call and shared
/// thereafter; fields are internal, reached through
/// [`SemanticModel`]'s accessors.
pub struct Built<'a> {
    source: &'a str,
    scopes: Vec<Scope>,
    bindings: Vec<Binding<'a>>,
    references: Vec<Reference<'a>>,
    with_sites: Vec<WithSite>,
    import_sites: Vec<ImportSite>,
}

/// Lazy semantic model over one parsed file.
pub struct SemanticModel<'a> {
    source: &'a str,
    root: &'a SyntaxNode,
    built: OnceLock<Built<'a>>,
}

impl<'a> SemanticModel<'a> {
    /// Wrap a parsed tree. Does no work: the build runs on the first
    /// accessor call and is cached.
    pub fn new(source: &'a str, root: &'a SyntaxNode) -> Self {
        Self {
            source,
            root,
            built: OnceLock::new(),
        }
    }

    /// The source text this model was built over.
    #[must_use]
    pub fn source(&self) -> &'a str {
        self.source
    }

    /// The parse tree this model was built over.
    #[must_use]
    pub fn root(&self) -> &'a SyntaxNode {
        self.root
    }

    /// Build once, then return the shared result. The build is
    /// idempotent: only the first call walks the tree.
    fn ensure_built(&self) -> &Built<'a> {
        self.built
            .get_or_init(|| Built::build(self.source, self.root))
    }

    /// All bindings, in declaration order.
    #[must_use]
    pub fn bindings(&self) -> &[Binding<'a>] {
        &self.ensure_built().bindings
    }

    /// All references in source order.
    #[must_use]
    pub fn references(&self) -> &[Reference<'a>] {
        &self.ensure_built().references
    }

    /// All `with` constructs, in source order.
    #[must_use]
    pub fn with_sites(&self) -> &[WithSite] {
        &self.ensure_built().with_sites
    }

    /// All `import` calls, in source order.
    #[must_use]
    pub fn import_sites(&self) -> &[ImportSite] {
        &self.ensure_built().import_sites
    }

    /// Resolve an ident token belonging to this tree: find the
    /// reference with the same byte range and return the binding it
    /// resolved to. Tokens that are not expression-position references
    /// (attrpath elements, inherit names, formals) yield `None`.
    ///
    /// Tokens are `Copy` values, so identity is compared by byte range
    /// — two tokens can never share a range within one tree.
    #[must_use]
    pub fn resolve(&self, token: &SyntaxToken) -> Option<&Binding<'a>> {
        let built = self.ensure_built();
        let idx = built
            .references
            .iter()
            .find(|r| r.name.range() == token.range())
            .and_then(|r| r.resolved)?;
        Some(&built.bindings[idx])
    }

    /// The nearest lexical binding for `name` visible at `offset`, or
    /// `None`. Scopes are searched innermost-out and the first binding
    /// whose scope rules make it visible at `offset` wins. No `with`
    /// fallback — use [`Self::is_bound`] for the with-aware answer.
    #[must_use]
    pub fn resolve_lexical(&self, name: &str, offset: u32) -> Option<&Binding<'a>> {
        let built = self.ensure_built();
        built
            .resolve_lexical_index(name, offset)
            .map(|i| &built.bindings[i])
    }

    /// Whether any binding — lexical, or any `with` whose body covers
    /// `offset` — could provide `name` at `offset`. The `with` side is
    /// deliberately conservative: statically we cannot know whether a
    /// with's attrset provides the name, so every covering with counts.
    #[must_use]
    pub fn is_bound(&self, name: &str, offset: u32) -> bool {
        let built = self.ensure_built();
        built.resolve_lexical_index(name, offset).is_some()
            || built
                .with_sites
                .iter()
                .any(|w| w.body_range.contains(offset))
    }
}

impl<'a> Built<'a> {
    /// The two-pass build described in the module docs.
    fn build(source: &'a str, root: &'a SyntaxNode) -> Self {
        let mut builder = Builder {
            source,
            scopes: Vec::new(),
            bindings: Vec::new(),
            with_sites: Vec::new(),
            import_sites: Vec::new(),
            idents: Vec::new(),
            stack: Vec::new(),
        };
        builder.new_scope(ScopeKind::Root, root.range());
        if let Some(expr) = Root::cast(root).and_then(|r| r.expr()) {
            builder.walk_expr(expr);
        }
        let mut built = Self {
            source,
            scopes: builder.scopes,
            bindings: builder.bindings,
            references: Vec::new(),
            with_sites: builder.with_sites,
            import_sites: builder.import_sites,
        };
        for token in builder.idents {
            built.record_reference(token);
        }
        built
    }

    /// Record one reference and resolve it against the finished scope
    /// table, filling both the reference's fields and the resolved
    /// binding's `references`.
    fn record_reference(&mut self, token: &'a SyntaxToken) {
        let offset = token.range().start();
        let name = token.text(self.source);
        let resolved = self.resolve_lexical_index(name, offset);
        let via_with = if resolved.is_none() {
            self.with_fallback(offset)
        } else {
            None
        };
        if let Some(bi) = resolved {
            self.bindings[bi].references.push(token.range());
        }
        self.references.push(Reference {
            name: token,
            resolved,
            via_with,
        });
    }

    /// The innermost scope whose range contains `offset`. Scopes nest
    /// strictly (each new scope's range lies inside its parent's) and
    /// are created depth-first in source order, so the last scope
    /// containing the offset is the innermost.
    fn innermost_scope(&self, offset: u32) -> Option<ScopeId> {
        self.scopes
            .iter()
            .enumerate()
            .rev()
            .find(|(_, s)| s.range.contains(offset))
            .map(|(i, _)| ScopeId(i as u32))
    }

    /// The innermost `with` whose body contains `offset`, if any. Sites
    /// are recorded in source order and nested bodies are subranges, so
    /// a reverse scan finds the innermost one first.
    fn with_fallback(&self, offset: u32) -> Option<usize> {
        self.with_sites
            .iter()
            .enumerate()
            .rev()
            .find(|(_, w)| w.body_range.contains(offset))
            .map(|(i, _)| i)
    }

    /// Lexical resolution: walk scopes outward from the innermost one
    /// containing `offset`; the first binding whose name matches and
    /// whose scope rules make it visible at `offset` wins.
    fn resolve_lexical_index(&self, name: &str, offset: u32) -> Option<usize> {
        let mut scope_id = self.innermost_scope(offset)?;
        loop {
            let scope = &self.scopes[scope_id.0 as usize];
            // Attrset scopes host inherit names but bind nothing for
            // resolution; Root, With, and empty slices fall through the
            // loop naturally.
            if scope.kind != ScopeKind::Attrset {
                for (pos, &bi) in scope.bindings.iter().enumerate() {
                    let binding = &self.bindings[bi];
                    if binding.name.text(self.source) == name
                        && self.is_visible(scope_id, pos, offset)
                    {
                        return Some(bi);
                    }
                }
            }
            scope_id = scope.parent?;
        }
    }

    /// Whether the binding at `pos` (within `scope_id`) is visible at
    /// `offset`. `let` and lambda scopes gate on their per-binding
    /// visibility start; rec scopes are visible everywhere in their
    /// range, which contains `offset` by construction.
    fn is_visible(&self, scope_id: ScopeId, pos: usize, offset: u32) -> bool {
        let scope = &self.scopes[scope_id.0 as usize];
        match scope.kind {
            ScopeKind::Let | ScopeKind::Lambda => {
                offset >= scope.visible_from[pos] && offset < scope.range.end()
            }
            ScopeKind::Rec => offset < scope.range.end(),
            _ => false,
        }
    }
}

/// Pass-1 scratch state: the walker's output plus the scope stack that
/// tracks which scope each newly created construct belongs to.
struct Builder<'a> {
    source: &'a str,
    scopes: Vec<Scope>,
    bindings: Vec<Binding<'a>>,
    with_sites: Vec<WithSite>,
    import_sites: Vec<ImportSite>,
    /// Expression-position ident tokens, in source order, resolved in
    /// pass 2 once every scope and binding exists.
    idents: Vec<&'a SyntaxToken>,
    stack: Vec<ScopeId>,
}

impl<'a> Builder<'a> {
    /// Open a scope as a child of the current one and make it current.
    fn new_scope(&mut self, kind: ScopeKind, range: TextRange) -> ScopeId {
        let parent = self.stack.last().copied();
        let id = ScopeId(self.scopes.len() as u32);
        self.scopes.push(Scope {
            kind,
            parent,
            range,
            bindings: Vec::new(),
            visible_from: Vec::new(),
        });
        self.stack.push(id);
        id
    }

    /// Close the current scope, restoring its parent.
    fn pop_scope(&mut self) {
        self.stack.pop();
    }

    /// Record one binding in `scope`, visible from `visible_from`.
    fn register(
        &mut self,
        name: &'a SyntaxToken,
        kind: BindingKind,
        scope: ScopeId,
        visible_from: u32,
    ) {
        let idx = self.bindings.len();
        self.bindings.push(Binding {
            name,
            kind,
            scope,
            references: Vec::new(),
        });
        let slot = &mut self.scopes[scope.0 as usize];
        slot.bindings.push(idx);
        slot.visible_from.push(visible_from);
    }

    /// The first plain-name element of a binding's attrpath: the single
    /// name that binding introduces. String-led paths (`"a".b = ...`)
    /// bind a name we cannot represent as one token, so they are
    /// skipped.
    fn binding_name(binding: &strictix_syntax::Binding<'a>) -> Option<&'a SyntaxToken> {
        match binding.attrpath()?.elements().next()? {
            AttrName::Ident(token) => Some(token),
            AttrName::Str(_) => None,
        }
    }

    /// Whether an application is an `import` call: `import arg` or
    /// `builtins.import arg`.
    fn is_import(source: &str, apply: &strictix_syntax::ApplyExpr<'a>) -> bool {
        match apply.func() {
            Some(Expr::Ident(token)) => token.text(source) == "import",
            Some(Expr::Select(select)) => {
                if !matches!(
                    select.base(),
                    Some(Expr::Ident(t)) if t.text(source) == "builtins"
                ) {
                    return false;
                }
                let mut elements = select
                    .attrpath()
                    .map(|ap| ap.elements())
                    .into_iter()
                    .flatten();
                let first_is_import = match elements.next() {
                    Some(AttrName::Ident(t)) => t.text(source) == "import",
                    _ => false,
                };
                first_is_import && elements.next().is_none()
            }
            _ => false,
        }
    }

    /// Walk one expression subtree: open scopes, register bindings,
    /// collect import sites, and push every expression-position ident
    /// token for pass 2. Malformed regions never reach this function —
    /// `Expr::cast` rejects ErrorNode subtrees — so a broken source
    /// yields an empty or partial model, never a panic.
    fn walk_expr(&mut self, expr: Expr<'a>) {
        match expr {
            Expr::Ident(token) => self.idents.push(token),
            Expr::Let(let_expr) => {
                let scope = self.new_scope(ScopeKind::Let, let_expr.range());
                if let Some(bindings) = let_expr.bindings() {
                    for item in bindings.items() {
                        match item {
                            AttrItem::Binding(binding) => {
                                // Sequential visibility: this binding
                                // becomes visible only after its own
                                // value ends, so the value resolves
                                // against earlier bindings and outer
                                // scopes only — the `let x = x;` gotcha.
                                // Declared before walking so bindings
                                // stay in name-token order; visibility
                                // is gated by visible_from, not by
                                // registration order.
                                if let Some(name) = Self::binding_name(&binding) {
                                    let visible_from = binding
                                        .value()
                                        .map(|v| v.range().end())
                                        .unwrap_or(binding.range().end());
                                    self.register(
                                        name,
                                        BindingKind::LetBinding,
                                        scope,
                                        visible_from,
                                    );
                                }
                                if let Some(value) = binding.value() {
                                    self.walk_expr(value);
                                }
                            }
                            AttrItem::Inherit(inherit) => {
                                if let Some(source) = inherit.source() {
                                    self.walk_expr(source);
                                }
                                // inherit binds its names at its own
                                // position: visible to later bindings
                                // and the body, not to earlier values.
                                let visible_from = inherit.range().end();
                                for name in inherit.names() {
                                    self.register(
                                        name,
                                        BindingKind::LetBinding,
                                        scope,
                                        visible_from,
                                    );
                                }
                            }
                        }
                    }
                }
                if let Some(body) = let_expr.body() {
                    self.walk_expr(body);
                }
                self.pop_scope();
            }
            Expr::Lambda(lambda) => {
                let scope = self.new_scope(ScopeKind::Lambda, lambda.range());
                match lambda.param() {
                    LambdaParam::Ident(token) => {
                        // `x: body` — x is visible in the body, never
                        // in itself.
                        self.register(token, BindingKind::LambdaParam, scope, token.range().end());
                    }
                    LambdaParam::Formals(formals, at_name) => {
                        for param in formals.params() {
                            if let Some(default) = param.default {
                                self.walk_expr(default);
                            }
                            // Sequential like let: param i is visible in
                            // the defaults of j > i and in the body; its
                            // own default (walked above) is excluded.
                            let visible_from = param
                                .default
                                .map(|d| d.range().end())
                                .unwrap_or(param.name.range().end());
                            self.register(
                                param.name,
                                BindingKind::LambdaParam,
                                scope,
                                visible_from,
                            );
                        }
                        if let Some(at) = at_name {
                            // The at-name is visible only in the body,
                            // whichever side of the formals it sits on.
                            let visible_from = formals.range().end().max(at.range().end());
                            self.register(at, BindingKind::AtName, scope, visible_from);
                        }
                    }
                }
                if let Some(body) = lambda.body() {
                    self.walk_expr(body);
                }
                self.pop_scope();
            }
            Expr::With(with_expr) => {
                // The scope expression is evaluated in the surrounding
                // scope, not the with's own.
                if let Some(scope_expr) = with_expr.scope() {
                    self.walk_expr(scope_expr);
                }
                if let Some(body) = with_expr.body() {
                    self.with_sites.push(WithSite {
                        scope_range: with_expr.range(),
                        body_range: body.range(),
                    });
                    // The with-scope governs only the body and never
                    // shadows: its binding set is empty, so resolution
                    // walks through it and the with shows up only as a
                    // via_with fallback.
                    self.new_scope(ScopeKind::With, body.range());
                    self.walk_expr(body);
                    self.pop_scope();
                }
            }
            Expr::Attrset(attrset) => {
                let scope = self.new_scope(ScopeKind::Attrset, attrset.range());
                for item in attrset.items() {
                    match item {
                        AttrItem::Binding(binding) => {
                            // A non-rec attrset binds nothing for
                            // resolution; only its values are walked.
                            if let Some(value) = binding.value() {
                                self.walk_expr(value);
                            }
                        }
                        AttrItem::Inherit(inherit) => {
                            if let Some(source) = inherit.source() {
                                self.walk_expr(source);
                            }
                            // Recorded (rules can see them) but never
                            // resolvable: the attrset scope is skipped
                            // during resolution.
                            let visible_from = inherit.range().end();
                            for name in inherit.names() {
                                self.register(name, BindingKind::InheritName, scope, visible_from);
                            }
                        }
                    }
                }
                self.pop_scope();
            }
            Expr::RecAttrset(rec) => {
                if let Some(attrset) = rec.attrset() {
                    let scope = self.new_scope(ScopeKind::Rec, attrset.range());
                    for item in attrset.items() {
                        match item {
                            AttrItem::Binding(binding) => {
                                // Register before walking the value:
                                // rec makes every name visible in every
                                // value, including earlier ones
                                // (`rec { b = a; a = 1; }` is valid).
                                if let Some(name) = Self::binding_name(&binding) {
                                    self.register(
                                        name,
                                        BindingKind::RecAttr,
                                        scope,
                                        attrset.range().start(),
                                    );
                                }
                                if let Some(value) = binding.value() {
                                    self.walk_expr(value);
                                }
                            }
                            AttrItem::Inherit(inherit) => {
                                if let Some(source) = inherit.source() {
                                    self.walk_expr(source);
                                }
                                for name in inherit.names() {
                                    self.register(
                                        name,
                                        BindingKind::RecAttr,
                                        scope,
                                        attrset.range().start(),
                                    );
                                }
                            }
                        }
                    }
                    self.pop_scope();
                }
            }
            Expr::Assert(assert_expr) => {
                if let Some(cond) = assert_expr.cond() {
                    self.walk_expr(cond);
                }
                if let Some(body) = assert_expr.body() {
                    self.walk_expr(body);
                }
            }
            Expr::If(if_expr) => {
                if let Some(cond) = if_expr.cond() {
                    self.walk_expr(cond);
                }
                if let Some(then_branch) = if_expr.then_branch() {
                    self.walk_expr(then_branch);
                }
                if let Some(else_branch) = if_expr.else_branch() {
                    self.walk_expr(else_branch);
                }
            }
            Expr::List(list) => {
                for item in list.items() {
                    self.walk_expr(item);
                }
            }
            Expr::Apply(apply) => {
                if Self::is_import(self.source, &apply) {
                    if let Some(arg) = apply.arg() {
                        self.import_sites.push(ImportSite {
                            call_range: apply.range(),
                            path_range: arg.range(),
                        });
                    }
                }
                if let Some(func) = apply.func() {
                    self.walk_expr(func);
                }
                if let Some(arg) = apply.arg() {
                    self.walk_expr(arg);
                }
            }
            Expr::Unary(unary) => {
                if let Some(operand) = unary.operand() {
                    self.walk_expr(operand);
                }
            }
            Expr::Bin(bin) => {
                if let Some(lhs) = bin.lhs() {
                    self.walk_expr(lhs);
                }
                if let Some(rhs) = bin.rhs() {
                    self.walk_expr(rhs);
                }
            }
            Expr::Select(select) => {
                if let Some(base) = select.base() {
                    self.walk_expr(base);
                }
                // The attrpath (`b` in `a.b`) is NOT an expression
                // position: field names are never references. Only the
                // `or default` part is walked.
                if let Some(default) = select.default() {
                    self.walk_expr(default);
                }
            }
            Expr::HasAttr(has_attr) => {
                // `x ? a.b` — the right side is an attribute path, not
                // a reference, even though the parser represents it as
                // an expression.
                if let Some(base) = has_attr.base() {
                    self.walk_expr(base);
                }
            }
            Expr::String(string) => self.walk_string_parts(string.parts()),
            Expr::IndString(string) => self.walk_string_parts(string.parts()),
            Expr::Paren(paren) => {
                if let Some(inner) = paren.expr() {
                    self.walk_expr(inner);
                }
            }
            Expr::Int(_) | Expr::Float(_) | Expr::Path(_) | Expr::SearchPath(_) | Expr::Uri(_) => {}
        }
    }

    /// Walk the interpolated subexpressions of a string. Interpolations
    /// ARE expression positions; literal content is not.
    fn walk_string_parts(&mut self, parts: impl IntoIterator<Item = StringPart<'a>>) {
        for part in parts {
            if let StringPart::Interp(interp) = part {
                if let Some(inner) = interp.expr() {
                    self.walk_expr(inner);
                }
            }
        }
    }
}

//! A minimal, dependency-free JSON parser (M8).
//!
//! strictix's blessed dependencies are serde + toml, and only inside the
//! CLI crate. The core crate therefore parses options.json (nixpkgs
//! schema data) by hand. This module implements the full JSON grammar:
//! objects, arrays, strings with escapes (including \uXXXX surrogate
//! pairs), numbers, true/false/null, and arbitrary whitespace.
//! Trailing non-whitespace content is rejected.
//!
//! The parser never panics: every malformed input yields a
//! [JsonError] carrying a message and the byte offset where the
//! problem was detected.

/// A parsed JSON value.
///
/// Objects keep their entries in insertion order as a Vec of key/value
/// pairs; duplicate keys are kept (both entries survive), per the
/// contract.
#[derive(Clone, Debug, PartialEq)]
pub enum JsonValue {
    /// The JSON literal null.
    Null,
    /// The JSON literals true and false.
    Bool(bool),
    /// A JSON number, stored as an f64.
    Number(f64),
    /// A JSON string, decoded: escapes and \uXXXX sequences are
    /// resolved to their UTF-8 text.
    String(String),
    /// A JSON array.
    Array(Vec<JsonValue>),
    /// A JSON object; entries in source order.
    Object(Vec<(String, JsonValue)>),
}

/// A JSON parse failure: a human-readable message plus the byte offset
/// in the input where the error was detected.
#[derive(Debug, PartialEq, Eq)]
pub struct JsonError {
    /// What went wrong.
    pub message: String,
    /// Byte offset into the input where the error was detected.
    pub offset: usize,
}

impl JsonValue {
    /// Parse a complete JSON document from input.
    ///
    /// Leading and trailing whitespace (space, tab, LF, CR) is skipped;
    /// any non-whitespace content after the first value is an error.
    pub fn parse(input: &str) -> Result<JsonValue, JsonError> {
        let mut parser = Parser { input, pos: 0 };
        parser.skip_ws();
        let value = parser.value()?;
        parser.skip_ws();
        if parser.peek_byte().is_some() {
            return Err(parser.error("trailing content"));
        }
        Ok(value)
    }

    /// Object lookup: the first entry whose key equals key, or None
    /// when this is not an object or the key is absent.
    #[must_use]
    pub fn get(&self, key: &str) -> Option<&JsonValue> {
        match self {
            JsonValue::Object(entries) => entries.iter().find(|(k, _)| k == key).map(|(_, v)| v),
            _ => None,
        }
    }

    /// This value as a string, if it is one.
    #[must_use]
    pub fn as_str(&self) -> Option<&str> {
        match self {
            JsonValue::String(s) => Some(s),
            _ => None,
        }
    }

    /// This value as a bool, if it is one.
    #[must_use]
    pub fn as_bool(&self) -> Option<bool> {
        match self {
            JsonValue::Bool(b) => Some(*b),
            _ => None,
        }
    }

    /// This value as an array slice, if it is one.
    #[must_use]
    pub fn as_array(&self) -> Option<&[JsonValue]> {
        match self {
            JsonValue::Array(items) => Some(items),
            _ => None,
        }
    }

    /// This value as an object's entries in insertion order, if it is
    /// one.
    #[must_use]
    pub fn as_object(&self) -> Option<&[(String, JsonValue)]> {
        match self {
            JsonValue::Object(entries) => Some(entries),
            _ => None,
        }
    }
}

/// Byte-cursor parser over a &str. pos is always on a UTF-8
/// character boundary, so byte offsets reported in errors match the
/// input.
struct Parser<'a> {
    input: &'a str,
    pos: usize,
}

impl Parser<'_> {
    /// The byte at pos, if any.
    fn peek_byte(&self) -> Option<u8> {
        self.input.as_bytes().get(self.pos).copied()
    }

    /// An error reported at the current position.
    fn error(&self, message: &str) -> JsonError {
        JsonError {
            message: message.to_owned(),
            offset: self.pos,
        }
    }

    ///

//! Lexer, parser, lossless syntax tree, and typed AST for the Nix
//! expression language.
//!
//! Everything in this crate is owned: no rowan, no rnix. The lexer
//! produces a flat token stream; the parser assembles it into a
//! lossless concrete syntax tree (whitespace and comments are preserved
//! as trivia) so that automatic fixes never destroy formatting. The
//! typed AST layer ([ast]) adds shape-aware wrappers over the tree.
//!
//! Error recovery is built in: malformed input yields a tree with
//! [SyntaxKind::ErrorNode] regions, never a panic or an abort.

#![forbid(unsafe_code)]

mod ast;
mod green;
mod kind;
mod lexer;
mod parser;

pub use ast::*;
pub use green::{NodeOrToken, SyntaxNode, SyntaxToken, TextRange};
pub use kind::SyntaxKind;
pub use lexer::{lex, Token};
pub use parser::parse;

//! Lossless green tree: nodes, tokens, and text ranges.
//!
//! The parser produces an immutable, lossless concrete syntax tree
//! (CST). Every token from the lexer — including whitespace and comments
//! (trivia) — is preserved so that reconstructing all token texts in
//! order reproduces the source byte-for-byte. This is what lets
//! future fixes edit text without destroying formatting.

use crate::kind::SyntaxKind;

/// A half-open byte range `[start, end)` into the source text.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct TextRange {
    start: u32,
    end: u32,
}

impl TextRange {
    /// Create a range `[start, end)`. Panics (in debug) if `start > end`.
    #[must_use]
    pub fn new(start: u32, end: u32) -> Self {
        debug_assert!(start <= end, "invalid range {start}..{end}");
        Self { start, end }
    }

    /// The inclusive start offset.
    #[must_use]
    pub const fn start(self) -> u32 {
        self.start
    }

    /// The exclusive end offset.
    #[must_use]
    pub const fn end(self) -> u32 {
        self.end
    }

    /// Whether the range covers no text.
    #[must_use]
    pub const fn is_empty(self) -> bool {
        self.start == self.end
    }

    /// Whether `offset` falls inside `[start, end)`.
    #[must_use]
    pub const fn contains(self, offset: u32) -> bool {
        self.start <= offset && offset < self.end
    }
}

/// A single token in the CST. Trivia (whitespace, comments) are ordinary
/// tokens preserved in the tree for lossless round-trips.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SyntaxToken {
    pub kind: SyntaxKind,
    pub range: TextRange,
}

impl SyntaxToken {
    /// The kind of this token.
    #[must_use]
    pub const fn kind(self) -> SyntaxKind {
        self.kind
    }

    /// The byte range this token covers.
    #[must_use]
    pub const fn range(self) -> TextRange {
        self.range
    }

    /// The source text this token covers.
    #[must_use]
    pub fn text(self, source: &str) -> &str {
        let start = self.range.start as usize;
        &source[start..start + self.range.len() as usize]
    }
}

impl TextRange {
    const fn len(self) -> u32 {
        self.end - self.start
    }
}

/// Either a child node or a token in a node's children list.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum NodeOrToken {
    Node(SyntaxNode),
    Token(SyntaxToken),
}

impl NodeOrToken {
    /// The kind of this child.
    #[must_use]
    pub fn kind(&self) -> SyntaxKind {
        match self {
            NodeOrToken::Node(n) => n.kind,
            NodeOrToken::Token(t) => t.kind,
        }
    }

    /// The byte range covered by this child.
    #[must_use]
    pub fn range(&self) -> TextRange {
        match self {
            NodeOrToken::Node(n) => n.range,
            NodeOrToken::Token(t) => t.range,
        }
    }
}

/// A node in the lossless concrete syntax tree.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SyntaxNode {
    kind: SyntaxKind,
    children: Vec<NodeOrToken>,
    range: TextRange,
}

impl SyntaxNode {
    /// This node's kind.
    #[must_use]
    pub const fn kind(&self) -> SyntaxKind {
        self.kind
    }

    /// The byte range covered by this node and all its descendants.
    #[must_use]
    pub const fn range(&self) -> TextRange {
        self.range
    }

    /// The direct children of this node, in source order.
    #[must_use]
    pub fn children(&self) -> &[NodeOrToken] {
        &self.children
    }
    /// The child nodes (excluding tokens) of this node, in source order.
    pub fn child_nodes(&self) -> impl Iterator<Item = &SyntaxNode> {
        self.children.iter().filter_map(|c| match c {
            NodeOrToken::Node(n) => Some(n),
            NodeOrToken::Token(_) => None,
        })
    }

    /// The child tokens (excluding nodes) of this node, in source order.
    pub fn child_tokens(&self) -> impl Iterator<Item = &SyntaxToken> {
        self.children.iter().filter_map(|c| match c {
            NodeOrToken::Token(t) => Some(t),
            NodeOrToken::Node(_) => None,
        })
    }

    /// The first child node of the given kind, if any.
    #[must_use]
    pub fn child_node(&self, kind: SyntaxKind) -> Option<&SyntaxNode> {
        self.child_nodes().find(|n| n.kind() == kind)
    }

    /// All child nodes of the given kind, in source order.
    pub fn child_nodes_of_kind(&self, kind: SyntaxKind) -> impl Iterator<Item = &SyntaxNode> {
        self.child_nodes().filter(move |n| n.kind() == kind)
    }

    /// All descendant nodes, depth-first pre-order, self first.
    pub fn descendants(&self) -> impl Iterator<Item = &SyntaxNode> {
        let mut stack = vec![self];
        std::iter::from_fn(move || {
            let node = stack.pop()?;
            let children: Vec<_> = node.child_nodes().collect();
            stack.extend(children.into_iter().rev());
            Some(node)
        })
    }
    /// The source text this node covers.
    #[must_use]
    pub fn text<'a>(&self, source: &'a str) -> &'a str {
        let start = self.range.start as usize;
        &source[start..self.range().len() as usize + start]
    }

    /// Reconstruct all token texts in this subtree, in source order.
    ///
    /// For a well-formed tree this reproduces the source exactly.
    #[must_use]
    pub fn reassemble(&self, source: &str) -> String {
        let mut out = String::new();
        self.reassemble_into(source, &mut out);
        out
    }

    fn reassemble_into(&self, source: &str, out: &mut String) {
        for child in &self.children {
            match child {
                NodeOrToken::Node(node) => node.reassemble_into(source, out),
                NodeOrToken::Token(token) => out.push_str(token.text(source)),
            }
        }
    }
}

/// Incremental builder that assembles a [`SyntaxNode`] tree from a
/// stream of `start` / `token` / `finish` events. Node ranges are
/// computed from their children when the node is closed.
#[derive(Default)]
pub struct TreeBuilder {
    stack: Vec<OpenNode>,
    root: Option<SyntaxNode>,
    /// End offset of the last token emitted; used to give empty nodes a
    /// sensible (empty) range at the current position.
    last_end: u32,
}

struct OpenNode {
    kind: SyntaxKind,
    children: Vec<NodeOrToken>,
}

impl TreeBuilder {
    /// Start a new node with the given kind.
    pub fn start(&mut self, kind: SyntaxKind) {
        self.stack.push(OpenNode {
            kind,
            children: Vec::new(),
        });
    }

    /// Emit a token as a child of the innermost open node.
    pub fn token(&mut self, kind: SyntaxKind, range: TextRange) {
        self.last_end = range.end();
        let token = SyntaxToken { kind, range };
        match self.stack.last_mut() {
            Some(node) => node.children.push(NodeOrToken::Token(token)),
            None => {
                // A token outside any node should not happen; the parser
                // always wraps everything in a Root. Defensive no-op.
            }
        }
    }

    /// Close the innermost open node, computing its range from children.
    pub fn finish(&mut self) {
        let node = self.stack.pop().expect("finish without open node");
        let range = match (node.children.first(), node.children.last()) {
            (Some(first), Some(last)) => TextRange::new(first.range().start(), last.range().end()),
            _ => TextRange::new(self.last_end, self.last_end),
        };
        let node = SyntaxNode {
            kind: node.kind,
            children: node.children,
            range,
        };
        match self.stack.last_mut() {
            Some(parent) => parent.children.push(NodeOrToken::Node(node)),
            None => self.root = Some(node),
        }
    }

    /// Close any remaining open nodes and return the root.
    pub fn finish_all(mut self) -> SyntaxNode {
        while !self.stack.is_empty() {
            self.finish();
        }
        self.root.expect("no root node was produced")
    }
}

//! Node rules: syntax-level lints that fire on one node kind each.
//!
//! These are the structural rules — they look only at the lossless tree,
//! never at meaning. Each rule declares its node kind via
//! [Rule::node_kind] and inspects exactly those nodes in
//! [Rule::check_node]. They never touch the semantic model, so a run
//! with only node rules enabled never builds it.

use strictix_core::{
    diagnostic::{Diagnostic, Severity},
    fix::Fix,
    rules::Rule,
};
use strictix_syntax::SyntaxKind as K;
use strictix_syntax::{
    AssertExpr, AstNode, BinExpr, Expr, IfExpr, SyntaxKind, SyntaxNode, TextRange,
};

/// Flags `if`-expressions whose condition is the literal `true` or
/// `false`.
///
/// A constant condition makes one branch dead by construction. This is
/// classic AI-generated slop — `if true then a else b` is just `a` —
/// so the rule offers a fix that inlines the live branch.
pub struct ConstantIf;

impl Rule for ConstantIf {
    fn code(&self) -> &'static str {
        "constant-if"
    }

    fn name(&self) -> &'static str {
        "Constant condition"
    }

    fn description(&self) -> &'static str {
        "Flags if-expressions whose condition is the literal true or false. One branch is dead by construction; the live branch can be inlined (the fix does exactly that)."
    }

    fn severity(&self) -> Severity {
        Severity::Warning
    }

    fn node_kind(&self) -> Option<SyntaxKind> {
        Some(K::IfExpr)
    }

    fn check_node(&self, node: &SyntaxNode, source: &str, diags: &mut Vec<Diagnostic>) {
        let Some(if_expr) = IfExpr::cast(node) else {
            return;
        };
        let Some(cond) = if_expr.cond() else { return };
        // In Nix, true/false lex as Ident tokens. A *binding* named true
        // is legal ({ true = 1; }), but in expression position these
        // texts are always the literals — match on the exact text, which
        // is the only way to tell the two apart.
        let is_true = matches!(cond, Expr::Ident(t) if t.text(source) == "true");
        let is_false = matches!(cond, Expr::Ident(t) if t.text(source) == "false");
        if !is_true && !is_false {
            return;
        }
        let branch = if is_true {
            if_expr.then_branch()
        } else {
            if_expr.else_branch()
        };
        let mut diag = Diagnostic::new(
            "constant-if",
            Severity::Warning,
            "constant condition in if",
            node.range(),
        );
        if let Some(branch_expr) = branch {
            let label = if is_true {
                "replace with then branch"
            } else {
                "replace with else branch"
            };
            let fix = Fix::new(label).edit(node.range(), branch_expr.text(source));
            diag = diag.with_fix(fix);
        }
        diags.push(diag);
    }
}

/// Flags `assert true;` — a precondition that can never fail.
///
/// An assertion of a statically-true condition adds noise without
/// checking anything. The fix drops the `assert true;` prefix, keeping
/// the body.
pub struct AssertTrue;

impl Rule for AssertTrue {
    fn code(&self) -> &'static str {
        "assert-true"
    }

    fn name(&self) -> &'static str {
        "Assert always true"
    }

    fn description(&self) -> &'static str {
        "Flags assert-expressions whose condition is the literal true. The assertion never fails, so it guards nothing; the fix removes the dead prefix."
    }

    fn severity(&self) -> Severity {
        Severity::Warning
    }

    fn node_kind(&self) -> Option<SyntaxKind> {
        Some(K::AssertExpr)
    }

    fn check_node(&self, node: &SyntaxNode, source: &str, diags: &mut Vec<Diagnostic>) {
        let Some(assert_expr) = AssertExpr::cast(node) else {
            return;
        };
        let Some(cond) = assert_expr.cond() else {
            return;
        };
        // Same exact-text check as constant-if: true is an Ident token,
        // and in expression position that text is always the literal.
        let is_true = matches!(cond, Expr::Ident(t) if t.text(source) == "true");
        if !is_true {
            return;
        }
        let mut diag = Diagnostic::new(
            "assert-true",
            Severity::Warning,
            "assert true is always satisfied",
            node.range(),
        );
        // The AssertExpr node's range runs through the body, so the fix
        // targets assert-start .. the semicolon that ends the condition.
        // Only direct-child semicolons qualify — a semicolon inside the
        // body belongs to a child node and is never the terminator here.
        if let Some(semi) = node.child_tokens().find(|t| t.kind() == K::Semicolon) {
            let range = TextRange::new(node.range().start(), semi.range().end());
            let fix = Fix::new("remove assert true").edit(range, "");
            diag = diag.with_fix(fix);
        }
        diags.push(diag);
    }
}

/// Flags binary comparisons of an atom with itself.
///
/// `x == x`, `x != x`, `x && x`, and `x || x` have a fixed truth value
/// for any `x`. Only same-kind atoms with identical source text are
/// compared: `1 == 1` is flagged, `1 == 1.0` is not (the texts differ
/// in kind, and floats and ints are not equal in Nix).
pub struct Tautology;

impl Rule for Tautology {
    fn code(&self) -> &'static str {
        "tautology"
    }

    fn name(&self) -> &'static str {
        "Tautological comparison"
    }

    fn description(&self) -> &'static str {
        "Flags binary expressions comparing an atom with itself (x == x, x != x, x && x, x || x), which have a fixed truth value. AI-generated Nix often repeats an operand to pad a condition; the comparison is dead code."
    }

    fn severity(&self) -> Severity {
        Severity::Warning
    }

    fn node_kind(&self) -> Option<SyntaxKind> {
        Some(K::BinExpr)
    }

    fn check_node(&self, node: &SyntaxNode, source: &str, diags: &mut Vec<Diagnostic>) {
        let Some(bin_expr) = BinExpr::cast(node) else {
            return;
        };
        let Some(op) = bin_expr.op() else { return };
        if !matches!(op, K::EqEq | K::Neq | K::AndAnd | K::OrOr) {
            return;
        }
        let (Some(lhs), Some(rhs)) = (bin_expr.lhs(), bin_expr.rhs()) else {
            return;
        };
        // Same kind AND identical text: Ident vs Ident, Int vs Int. A
        // float is a different kind, so 1 == 1.0 never matches.
        let same_kind = matches!(
            (lhs, rhs),
            (Expr::Ident(_), Expr::Ident(_)) | (Expr::Int(_), Expr::Int(_))
        );
        let same_text = atom_text(lhs, source)
            .zip(atom_text(rhs, source))
            .map_or(false, |(l, r)| l == r);
        if same_kind && same_text {
            diags.push(Diagnostic::new(
                "tautology",
                Severity::Warning,
                "tautological comparison",
                node.range(),
            ));
        }
    }
}

/// The source text of an ident or int atom; `None` for anything else.
///
/// Tautology compares atoms only — the same-kind guard then keeps the
/// two sides' kinds aligned (Ident/Ident, Int/Int).
fn atom_text<'a>(expr: Expr<'a>, source: &'a str) -> Option<&'a str> {
    match expr {
        Expr::Ident(t) | Expr::Int(t) => Some(t.text(source)),
        _ => None,
    }
}

//! File rules: semantic lints that run once per file against the lazy
//! [SemanticModel].
//!
//! Node rules in [super::node_rules] inspect single nodes; these rules
//! answer questions that need the whole file's meaning: is this let
//! binding ever used, does this lambda parameter shadow an outer one,
//! is this with scope doing any work. Every rule here is a unit struct
//! implementing [Rule] with only [Rule::check_file] overridden — the
//! registry ([super::all_rules]) declares them all the same way.

use strictix_core::config::LintConfig;
use strictix_core::diagnostic::{Diagnostic, Severity};
use strictix_core::fix::Fix;
use strictix_core::rules::Rule;
use strictix_core::semantic::{BindingKind, SemanticModel};
use strictix_syntax::{AstNode, Binding, Formals, SyntaxKind, SyntaxNode, TextRange};

/// The innermost [Binding] node whose range contains `name_range`, if
/// any. Bindings nest when a value contains a `let` or attrset, so a
/// range scan must pick the smallest containing node — the direct
/// parent of the name token — not the first one found.
fn containing_binding<'a>(root: &'a SyntaxNode, name_range: TextRange) -> Option<Binding<'a>> {
    let start = name_range.start();
    root.descendants()
        .filter(|n| n.kind() == SyntaxKind::Binding && n.range().contains(start))
        .min_by_key(|n| n.range().end() - n.range().start())
        .and_then(Binding::cast)
}

/// Whether `name_range` sits inside a Formals node. A lambda's bare
/// ident parameter is not inside one; its formal parameters are.
fn inside_formals(root: &SyntaxNode, name_range: TextRange) -> bool {
    let start = name_range.start();
    root.descendants()
        .any(|n| n.kind() == SyntaxKind::Formals && n.range().contains(start))
}

/// The innermost [Formals] node whose range contains `name_range`.
/// Formals can nest when a formal's default is itself a lambda, so the
/// smallest containing node is the one that actually owns the
/// parameter.
fn containing_formals<'a>(root: &'a SyntaxNode, name_range: TextRange) -> Option<Formals<'a>> {
    let start = name_range.start();
    root.descendants()
        .filter(|n| n.kind() == SyntaxKind::Formals && n.range().contains(start))
        .min_by_key(|n| n.range().end() - n.range().start())
        .and_then(Formals::cast)
}

/// Flags `let` bindings that are never referenced.
///
/// `let x = 1; in 2` — `x` is dead weight. The suggested fix deletes
/// the whole binding statement.
pub struct UnusedLetBinding;

impl Rule for UnusedLetBinding {
    fn code(&self) -> &'static str {
        "unused-let-binding"
    }

    fn name(&self) -> &'static str {
        "Unused let binding"
    }

    fn description(&self) -> &'static str {
        "Flags let bindings that are never referenced. Dead bindings are misleading and can be removed."
    }

    fn severity(&self) -> Severity {
        Severity::Warning
    }

    fn check_file(&self, model: &SemanticModel, _config: &LintConfig, diags: &mut Vec<Diagnostic>) {
        for binding in model.bindings() {
            if binding.kind != BindingKind::LetBinding || !binding.references.is_empty() {
                continue;
            }
            let name = binding.name.text(model.source());
            let range = binding.name.range();
            let mut diag = Diagnostic::new(
                self.code(),
                self.severity(),
                format!("binding '{name}' is never used"),
                range,
            );
            if let Some(binding_node) = containing_binding(model.root(), range) {
                diag =
                    diag.with_fix(Fix::new("remove unused binding").edit(binding_node.range(), ""));
            }
            diags.push(diag);
        }
    }
}

/// Flags bare lambda parameters that are never used.
///
/// `x: 1` — the parameter `x` is never referenced in the body. Formal
/// parameters (`{ a, b }: ...`) are handled by [UnusedFormal] because
/// they follow a different rule (the ellipsis changes what counts).
pub struct UnusedLambdaParam;

impl Rule for UnusedLambdaParam {
    fn code(&self) -> &'static str {
        "unused-lambda-param"
    }

    fn name(&self) -> &'static str {
        "Unused lambda parameter"
    }

    fn description(&self) -> &'static str {
        "Flags bare lambda parameters that are never used in the body. An unused parameter is usually a mistake; a leading underscore name opts out."
    }

    fn severity(&self) -> Severity {
        Severity::Warning
    }

    fn check_file(&self, model: &SemanticModel, _config: &LintConfig, diags: &mut Vec<Diagnostic>) {
        for binding in model.bindings() {
            if binding.kind != BindingKind::LambdaParam {
                continue;
            }
            let range = binding.name.range();
            // Formal parameters belong to UnusedFormal; this rule only
            // covers the bare `x: body` form.
            if inside_formals(model.root(), range) {
                continue;
            }
            if !binding.references.is_empty() {
                continue;
            }
            let name = binding.name.text(model.source());
            if name.starts_with('_') {
                continue;
            }
            diags.push(Diagnostic::new(
                self.code(),
                self.severity(),
                format!("parameter '{name}' is never used"),
                range,
            ));
        }
    }
}

/// Flags unused formal parameters of lambdas without an ellipsis.
///
/// `{ a, b }: b` — `a` is declared but never used. With an ellipsis
/// (`{ a, b, ... }: b`) the extra formals are an intentional interface,
/// so only `_`-prefixed names are exempt otherwise.
pub struct UnusedFormal;

impl Rule for UnusedFormal {
    fn code(&self) -> &'static str {
        "unused-formal"
    }

    fn name(&self) -> &'static str {
        "Unused formal parameter"
    }

    fn description(&self) -> &'static str {
        "Flags formal parameters that are never used when the formals have no ellipsis. An ellipsis signals an open argument set, so unused names there are tolerated."
    }

    fn severity(&self) -> Severity {
        Severity::Warning
    }

    fn check_file(&self, model: &SemanticModel, _config: &LintConfig, diags: &mut Vec<Diagnostic>) {
        for binding in model.bindings() {
            if binding.kind != BindingKind::LambdaParam {
                continue;
            }
            let range = binding.name.range();
            let Some(formals) = containing_formals(model.root(), range) else {
                continue; // bare ident param — UnusedLambdaParam's job
            };
            if formals.has_ellipsis() {
                continue;
            }
            if !binding.references.is_empty() {
                continue;
            }
            let name = binding.name.text(model.source());
            if name.starts_with('_') {
                continue;
            }
            diags.push(Diagnostic::new(
                self.code(),
                self.severity(),
                format!("parameter '{name}' is never used"),
                range,
            ));
        }
    }
}

/// Flags bindings whose name re-binds one already visible.
///
/// `let a = 1; in let a = 2; in a` — the inner `a` hides the outer one,
/// which is almost always a mistake (the outer binding is still
/// reachable, just under a different shadow).
pub struct ShadowedBinding;

impl Rule for ShadowedBinding {
    fn code(&self) -> &'static str {
        "shadowed-binding"
    }

    fn name(&self) -> &'static str {
        "Shadowed binding"
    }

    fn description(&self) -> &'static str {
        "Flags a binding whose name is already bound and visible at its own position. Shadowing hides the outer binding from every use after this point, which is usually unintended."
    }

    fn severity(&self) -> Severity {
        Severity::Warning
    }

    fn check_file(&self, model: &SemanticModel, _config: &LintConfig, diags: &mut Vec<Diagnostic>) {
        let bindings = model.bindings();
        for (idx, binding) in bindings.iter().enumerate() {
            let name = binding.name.text(model.source());
            let offset = binding.name.range().start();
            let Some(other) = model.resolve_lexical(name, offset) else {
                continue;
            };
            // Identity by index: rec attrs see their own name at the
            // attr-name position (rec binds inside values, but the
            // model is position-based), which is not a shadow.
            let other_idx = bindings.iter().position(|b| std::ptr::eq(b, other));
            if other_idx == Some(idx) {
                continue;
            }
            diags.push(Diagnostic::new(
                self.code(),
                self.severity(),
                format!("binding '{name}' shadows an outer binding"),
                binding.name.range(),
            ));
        }
    }
}

/// Flags `with` scopes whose body never needs them.
///
/// `let pkgs = ...; in with pkgs; pkgs.hello` — every name in the body
/// resolves lexically, so the `with` adds nothing.
pub struct RedundantWith;

impl Rule for RedundantWith {
    fn code(&self) -> &'static str {
        "redundant-with"
    }

    fn name(&self) -> &'static str {
        "Redundant with"
    }

    fn description(&self) -> &'static str {
        "Flags a with scope whose body references all resolve lexically — the with is never consulted and can be removed. Bodies with no references at all are left alone."
    }

    fn severity(&self) -> Severity {
        Severity::Warning
    }

    fn check_file(&self, model: &SemanticModel, _config: &LintConfig, diags: &mut Vec<Diagnostic>) {
        for site in model.with_sites() {
            let body_refs: Vec<_> = model
                .references()
                .iter()
                .filter(|r| {
                    let range = r.name.range();
                    site.body_range.contains(range.start()) && site.body_range.end() >= range.end()
                })
                .collect();
            if body_refs.is_empty() {
                continue;
            }
            let all_lexical = body_refs
                .iter()
                .all(|r| r.resolved.is_some() && r.via_with.is_none());
            if all_lexical {
                diags.push(Diagnostic::new(
                    self.code(),
                    self.severity(),
                    "with-scope is never used",
                    site.scope_range,
                ));
            }
        }
    }
}

/// Flags `let x = x;` infinite recursion.
///
/// A let binding is not visible in its own value, so `let x = x;` has
/// `x` on the right resolve to nothing — the classic AI-slop
/// infinite-recursion bug. A with-fallback or an outer binding that
/// could supply the name is not this bug.
pub struct SelfReferentialLet;

impl Rule for SelfReferentialLet {
    fn code(&self) -> &'static str {
        "self-referential-let"
    }

    fn name(&self) -> &'static str {
        "Self-referential let binding"
    }

    fn description(&self) -> &'static str {
        "Flags a let binding whose value references its own name with nothing else bound to that name — `let x = x;` evaluates to an infinite recursion at runtime."
    }

    fn severity(&self) -> Severity {
        Severity::Error
    }

    fn check_file(&self, model: &SemanticModel, _config: &LintConfig, diags: &mut Vec<Diagnostic>) {
        for binding in model.bindings() {
            if binding.kind != BindingKind::LetBinding {
                continue;
            }
            let Some(binding_node) = containing_binding(model.root(), binding.name.range()) else {
                continue;
            };
            let Some(value) = binding_node.value() else {
                continue;
            };
            let value_range = value.range();
            let name = binding.name.text(model.source());
            for reference in model.references() {
                let range = reference.name.range();
                if !(value_range.contains(range.start()) && value_range.end() >= range.end()) {
                    continue;
                }
                if reference.name.text(model.source()) != name {
                    continue;
                }
                if model.is_bound(name, range.start()) {
                    continue;
                }
                diags.push(Diagnostic::new(
                    self.code(),
                    self.severity(),
                    format!("binding '{name}' references itself: infinite recursion"),
                    binding.name.range(),
                ));
            }
        }
    }
}

//! Options-schema rule: flags NixOS option names that are not declared
//! in options.json (M8).
//!
//! NixOS modules consume their module arguments through the `config`
//! formal: `config.services.example.enable` reads an option. AI-generated
//! modules frequently hallucinate option names (`config.services.exmaple.enable`)
//! that exist nowhere in nixpkgs. This rule loads the options schema
//! (shape `{"options": {"a.b.c": {...}}}`) once per process, then walks
//! every select chain rooted at a `config` module argument and flags
//! full paths absent from the schema.
//!
//! The parsed schema lives in a process-wide [OnceLock] rather than a
//! field: rules are constructed by the registry macro as unit structs
//! (`Type {}`), so the struct itself carries no state. [OnceLock] is
//! Send + Sync, keeping the rule shareable across worker threads.

use std::collections::HashSet;
use std::path::Path;
use std::sync::OnceLock;

use strictix_core::config::LintConfig;
use strictix_core::diagnostic::{Diagnostic, Severity};
use strictix_core::json::JsonValue;
use strictix_core::rules::Rule;
use strictix_core::semantic::{BindingKind, Reference, SemanticModel};
use strictix_syntax::{AstNode, AttrName, Expr, SelectExpr};

/// The parsed options schema: the set of declared option paths, or the
/// reason loading/parsing failed. Loaded once per process.
type Schema = Result<HashSet<String>, String>;

static OPTIONS_SCHEMA: OnceLock<Schema> = OnceLock::new();

/// Read and parse options.json, extracting the `options` keys.
fn load_schema(path: &Path) -> Schema {
    let text = std::fs::read_to_string(path).map_err(|e| e.to_string())?;
    let parsed = JsonValue::parse(&text).map_err(|e| e.message)?;
    let options = parsed
        .get("options")
        .and_then(JsonValue::as_object)
        .ok_or_else(|| "expected a top-level \"options\" object".to_string())?;
    Ok(options.iter().map(|(key, _)| key.clone()).collect())
}

/// Whether a reference is a use of the `config` module argument: a
/// LambdaParam binding named `config`.
fn is_config_reference(model: &SemanticModel, reference: &Reference) -> bool {
    reference.name.text(model.source()) == "config"
        && model
            .resolve(reference.name)
            .is_some_and(|b| b.kind == BindingKind::LambdaParam)
}

/// The select chain rooted at `ref_range`: the innermost SelectExpr
/// whose base is the referenced ident, then every SelectExpr whose base
/// is the previous one (nested chains such as `Select(Select(config,a),b)`).
/// The parser usually flattens a path into one SelectExpr with a
/// multi-element attrpath, so the chain is typically a single node.
fn select_chain<'a>(
    model: &SemanticModel<'a>,
    ref_range: strictix_syntax::TextRange,
) -> Vec<SelectExpr<'a>> {
    let root = model.root();
    let mut chain = Vec::new();
    let Some(innermost) = root
        .descendants()
        .filter_map(SelectExpr::cast)
        .find(|s| matches!(s.base(), Some(Expr::Ident(t)) if t.range() == ref_range))
    else {
        return chain;
    };
    chain.push(innermost);
    let mut current_range = innermost.range();
    loop {
        let next = root
            .descendants()
            .filter_map(SelectExpr::cast)
            .find(|s| s.base().is_some_and(|b| b.range() == current_range));
        match next {
            Some(select) => {
                current_range = select.range();
                chain.push(select);
            }
            None => break,
        }
    }
    chain
}

/// Flags attribute paths read off `config` that options.json does not
/// declare.
///
/// Only fires when [LintConfig::schema] is set; the schema is loaded
/// lazily once. A load/parse failure is reported as a single diagnostic
/// on the first `config` reference, so a broken schema cannot crash
/// the run.
pub struct UnknownOption;

impl Rule for UnknownOption {
    fn code(&self) -> &'static str {
        "unknown-option"
    }

    fn name(&self) -> &'static str {
        "Unknown option"
    }

    fn description(&self) -> &'static str {
        "Flags option paths read off the config module argument that are not declared in options.json. Hallucinated option names are a classic failure mode of AI-generated NixOS modules."
    }

    fn severity(&self) -> Severity {
        Severity::Error
    }

    fn check_file(&self, model: &SemanticModel, config: &LintConfig, diags: &mut Vec<Diagnostic>) {
        let Some(path) = &config.schema else {
            return; // schema rule off for this run
        };
        let schema = OPTIONS_SCHEMA.get_or_init(|| load_schema(path));
        let options = match schema {
            Ok(options) => options,
            Err(err) => {
                if let Some(first) = model
                    .references()
                    .iter()
                    .find(|r| is_config_reference(model, r))
                {
                    diags.push(Diagnostic::new(
                        self.code(),
                        self.severity(),
                        format!("could not load options schema: {err}"),
                        first.name.range(),
                    ));
                }
                return;
            }
        };
        for reference in model.references() {
            if !is_config_reference(model, reference) {
                continue;
            }
            let chain = select_chain(model, reference.name.range());
            if chain.is_empty() {
                continue;
            }
            // Collect the path segments innermost-out, skipping chains
            // with any non-ident segment (strings, interpolations).
            let mut segments = Vec::new();
            let mut valid = true;
            for select in &chain {
                let Some(attrpath) = select.attrpath() else {
                    valid = false;
                    break;
                };
                for element in attrpath.elements() {
                    match element {
                        AttrName::Ident(token) => {
                            segments.push(token.text(model.source()).to_string())
                        }
                        AttrName::Str(_) => valid = false,
                    }
                }
            }
            if !valid {
                continue;
            }
            let full_path = segments.join(".");
            if options.contains(&full_path) {
                continue;
            }
            let range = chain
                .last()
                .and_then(|s| s.attrpath())
                .map(|a| a.range())
                .unwrap_or_else(|| chain.last().expect("chain is non-empty").range());
            diags.push(Diagnostic::new(
                self.code(),
                self.severity(),
                format!("option '{full_path}' is not declared in options.json"),
                range,
            ));
        }
    }
}

//! Integration tests for the file rules (semantic) and the schema rule.
//!
//! Each rule gets its positive case plus 2-3 false-positive guards:
//! well-formed code that must produce zero diagnostics. Diagnostics are
//! rendered with the one-line contract format
//! (`[code] severity start..end message`) and asserted exactly.

use std::path::PathBuf;

use strictix_core::config::LintConfig;
use strictix_core::diagnostic::Diagnostic;
use strictix_core::rules::{run_rules, Rule};
use strictix_core::semantic::SemanticModel;
use strictix_lints::file_rules::{
    RedundantWith, SelfReferentialLet, ShadowedBinding, UnusedFormal, UnusedLambdaParam,
    UnusedLetBinding,
};
use strictix_lints::schema::UnknownOption;
use strictix_syntax::parse;

/// Render diagnostics in the one-line contract format.
fn render(diags: &[Diagnostic]) -> Vec<String> {
    diags
        .iter()
        .map(|d| {
            format!(
                "[{}] {} {}..{} {}",
                d.code,
                d.severity_str(),
                d.range.start(),
                d.range.end(),
                d.message
            )
        })
        .collect()
}

/// Run `rules` over `source` with a fresh semantic model per source.
fn run(source: &str, rules: &[Box<dyn Rule>], config: LintConfig) -> Vec<String> {
    let tree = parse(source);
    let model = SemanticModel::new(source, &tree);
    let mut diags = Vec::new();
    run_rules(rules, &tree, &model, &config, source, &mut diags);
    render(&diags)
}

fn one(rule: Box<dyn Rule>) -> Vec<Box<dyn Rule>> {
    vec![rule]
}

/// All file rules plus the schema rule — used for the module fixtures'
/// "clean for ALL file rules" guarantee.
fn all_file_rules() -> Vec<Box<dyn Rule>> {
    vec![
        Box::new(UnusedLetBinding {}),
        Box::new(UnusedLambdaParam {}),
        Box::new(UnusedFormal {}),
        Box::new(ShadowedBinding {}),
        Box::new(RedundantWith {}),
        Box::new(SelfReferentialLet {}),
        Box::new(UnknownOption {}),
    ]
}

/// Read a fixture from tests/fixtures.
fn fixture(name: &str) -> String {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(name);
    std::fs::read_to_string(path).expect("fixture exists")
}

fn schema_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/options.json")
}

// --- unused-let-binding ---------------------------------------------

#[test]
fn unused_let_binding_flags_unused() {
    let rules = one(Box::new(UnusedLetBinding {}));
    let cfg = LintConfig::default();
    assert_eq!(
        run("let x = 1; in 2", &rules, cfg),
        ["[unused-let-binding] warning 4..5 binding 'x' is never used"]
    );
}

#[test]
fn unused_let_binding_clean_when_used() {
    let rules = one(Box::new(UnusedLetBinding {}));
    let cfg = LintConfig::default();
    assert_eq!(
        run("let x = 1; in x", &rules, cfg.clone()),
        Vec::<String>::new()
    );
    assert_eq!(
        run("let x = 1; y = x; in y", &rules, cfg),
        Vec::<String>::new()
    );
}

#[test]
fn unused_let_binding_offers_removal_fix() {
    let source = "let x = 1; in 2";
    let tree = parse(source);
    let model = SemanticModel::new(source, &tree);
    let mut diags = Vec::new();
    run_rules(
        &one(Box::new(UnusedLetBinding {})),
        &tree,
        &model,
        &LintConfig::default(),
        source,
        &mut diags,
    );
    let fix = diags[0].fix.as_ref().expect("unused binding gets a fix");
    assert_eq!(fix.label, "remove unused binding");
    assert_eq!(fix.edits.len(), 1);
    assert_eq!(fix.edits[0].replacement, "");
    assert_eq!(fix.edits[0].range.start(), 3);
    assert_eq!(fix.edits[0].range.end(), 10);
}

// --- unused-lambda-param --------------------------------------------

#[test]
fn unused_lambda_param_flags_unused() {
    let rules = one(Box::new(UnusedLambdaParam {}));
    let cfg = LintConfig::default();
    assert_eq!(
        run("x: 1", &rules, cfg),
        ["[unused-lambda-param] warning 0..1 parameter 'x' is never used"]
    );
}

#[test]
fn unused_lambda_param_clean_cases() {
    let rules = one(Box::new(UnusedLambdaParam {}));
    let cfg = LintConfig::default();
    assert_eq!(run("_x: 1", &rules, cfg.clone()), Vec::<String>::new());
    assert_eq!(run("x: x", &rules, cfg.clone()), Vec::<String>::new());
    // Only the inner y is unused; the outer x is referenced.
    assert_eq!(
        run("x: y: x", &rules, cfg),
        ["[unused-lambda-param] warning 3..4 parameter 'y' is never used"]
    );
}

// --- unused-formal ---------------------------------------------------

#[test]
fn unused_formal_flags_unused() {
    let rules = one(Box::new(UnusedFormal {}));
    let cfg = LintConfig::default();
    assert_eq!(
        run("{ a, b }: b", &rules, cfg),
        ["[unused-formal] warning 2..3 parameter 'a' is never used"]
    );
}

#[test]
fn unused_formal_clean_cases() {
    let rules = one(Box::new(UnusedFormal {}));
    let cfg = LintConfig::default();
    // Ellipsis means the extra formals are an open interface.
    assert_eq!(
        run("{ a, b, ... }: b", &rules, cfg.clone()),
        Vec::<String>::new()
    );
    // Underscore names opt out.
    assert_eq!(
        run("{ _a, b }: b", &rules, cfg.clone()),
        Vec::<String>::new()
    );
    // Used formals are fine.
    assert_eq!(run("{ a }: a", &rules, cfg), Vec::<String>::new());
}

// --- shadowed-binding ------------------------------------------------

#[test]
fn shadowed_binding_flags_inner() {
    let rules = one(Box::new(ShadowedBinding {}));
    let cfg = LintConfig::default();
    assert_eq!(
        run("let a = 1; in let a = 2; in a", &rules, cfg),
        ["[shadowed-binding] warning 18..19 binding 'a' shadows an outer binding"]
    );
}

#[test]
fn shadowed_binding_clean_cases() {
    let rules = one(Box::new(ShadowedBinding {}));
    let cfg = LintConfig::default();
    assert_eq!(
        run("let a = 1; in let b = 2; in a + b", &rules, cfg.clone()),
        Vec::<String>::new()
    );
    // A rec attr sees its own name at its position: not a shadow.
    assert_eq!(run("rec { a = 1; }", &rules, cfg), Vec::<String>::new());
}

// --- redundant-with --------------------------------------------------

#[test]
fn redundant_with_flags_when_body_is_lexical() {
    let rules = one(Box::new(RedundantWith {}));
    let cfg = LintConfig::default();
    // pkgs resolves lexically (to the let binding), so the with is dead.
    assert_eq!(
        run("let pkgs = 1; in with pkgs; pkgs.hello", &rules, cfg),
        ["[redundant-with] warning 16..38 with-scope is never used"]
    );
}

#[test]
fn redundant_with_flags_let_body() {
    let rules = one(Box::new(RedundantWith {}));
    let cfg = LintConfig::default();
    // x resolves to the let binding; the with attrset is never consulted.
    assert_eq!(
        run("let x = 1; in with { y = 2; }; x", &rules, cfg),
        ["[redundant-with] warning 13..32 with-scope is never used"]
    );
}

#[test]
fn redundant_with_clean_when_with_is_needed() {
    let rules = one(Box::new(RedundantWith {}));
    let cfg = LintConfig::default();
    // map/f/xs are unbound — the with scope is a real fallback.
    assert_eq!(
        run("with lib; map f xs", &rules, cfg.clone()),
        Vec::<String>::new()
    );
    // A single unbound reference needs the with too.
    assert_eq!(run("with lib; f", &rules, cfg), Vec::<String>::new());
}

// --- self-referential-let -------------------------------------------

#[test]
fn self_referential_let_flags_infinite_recursion() {
    let rules = one(Box::new(SelfReferentialLet {}));
    let cfg = LintConfig::default();
    assert_eq!(
        run("let x = x; in x", &rules, cfg.clone()),
        ["[self-referential-let] error 4..5 binding 'x' references itself: infinite recursion"]
    );
    assert_eq!(
        run("let x = x + 1; in x", &rules, cfg),
        ["[self-referential-let] error 4..5 binding 'x' references itself: infinite recursion"]
    );
}

#[test]
fn self_referential_let_clean_cases() {
    let rules = one(Box::new(SelfReferentialLet {}));
    let cfg = LintConfig::default();
    assert_eq!(
        run("let x = 1; in x", &rules, cfg.clone()),
        Vec::<String>::new()
    );
    // y is a different name — not self-reference.
    assert_eq!(run("let x = y; in x", &rules, cfg), Vec::<String>::new());
}

// --- unknown-option (schema rule) ------------------------------------

#[test]
fn unknown_option_flags_hallucinated_path() {
    let rules = all_file_rules();
    let cfg = LintConfig::default().with_schema(schema_path());
    let bad = fixture("module_bad.nix");
    assert_eq!(
        run(&bad, &rules, cfg),
        ["[unknown-option] error 24..47 option 'services.exmaple.enable' is not declared in options.json"]
    );
}

#[test]
fn unknown_option_clean_for_valid_module() {
    let rules = all_file_rules();
    let cfg = LintConfig::default().with_schema(schema_path());
    let ok = fixture("module_ok.nix");
    assert_eq!(run(&ok, &rules, cfg), Vec::<String>::new());
}

#[test]
fn unknown_option_off_without_schema() {
    let rules = all_file_rules();
    let cfg = LintConfig::default(); // schema None
    let bad = fixture("module_bad.nix");
    assert_eq!(run(&bad, &rules, cfg), Vec::<String>::new());
}
