fn process_file(
    path: &Path,
    rules: &[Box<dyn Rule>],
    config: &LintConfig,
    fix_mode: bool,
) -> FileResult {
    let source = match std::fs::read_to_string(path) {
        Ok(s) => s,
        Err(e) => {
            return FileResult {
                path: path.to_path_buf(),
                source: String::new(),
                diagnostics: Vec::new(),
                read_error: Some(format!("{}: {e}", path.display())),
                fixes_applied: 0,
                write_error: None,
                apply_error: None,
            };
        }
    };
    let tree = parse(&source);
    let model = SemanticModel::new(&source, &tree);
    let mut diagnostics = Vec::new();
    strictix_core::rules::run_rules(rules, &tree, &model, config, &source, &mut diagnostics);
    diagnostics.sort_by_key(|d| d.range.start());

    let (mut fixes_applied, mut write_error, mut apply_error) = (0, None, None);
    if fix_mode {
        let fix_count = diagnostics.iter().filter(|d| d.fix.is_some()).count();
        let edits: Vec<TextEdit> = diagnostics.iter().filter_map(|d| d.fix.as_ref()).flat_map(|f| f.edits.iter().cloned()).collect();
        match apply_fixes(&source, &edits) {
            Ok(fixed) if fixed != source => {
                match std::fs::write(path, &fixed) {
                    Ok(()) => fixes_applied = fix_count,
                    Err(e) => write_error = Some(e.to_string()),
                }
            }
            Ok(_) => {}
            Err(e) => apply_error = Some(format!("{e:?}")),
        }
    }

    FileResult { path: path.to_path_buf(), source, diagnostics, read_error: None, fixes_applied, write_error, apply_error }
}
