    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(!stdout.contains("dirty"), "ignored subdir is pruned: {stdout}");
    assert!(
        stdout.contains("0 diagnostics"),
        "only the clean file: {stdout}"
    );
}

